// Converte resultados em array de items para enviar WhatsApp
const input = $input.first().json;
const resultados = input.resultados || {};
const totalCidades = Object.keys(resultados).length;

const items = [];
let index = 1;

for (const [cidade, dados] of Object.entries(resultados)) {
  const success = dados.success || false;
  const faixas = dados.faixas || [];
  const error = dados.error || null;
  const operadoras = dados.operadoras_disponiveis || [];

  let msg = `*📍 COTAÇÃO ${index}/${totalCidades}*\n`;
  msg += `*${cidade}*\n`;
  msg += `─────────────────────────\n\n`;

  if (success && faixas.length > 0) {
    msg += `✅ Cotação Hapvida obtida\n\n`;
    faixas.forEach(f => {
      msg += `${f.faixa_etaria}: ${f.valor}\n`;
    });
  } else {
    msg += `❌ ${error || 'Hapvida não disponível'}\n`;
    if (operadoras.length > 0) {
      msg += `\nOperadoras disponíveis:\n`;
      operadoras.forEach(op => {
        msg += `• ${op}\n`;
      });
    }
  }

  items.push({ json: { mensagem: msg, cidade: cidade } });
  index++;
}

return items;
